//! Conditional ordering component only; not a market/key/UPS or whole-block certificate.
use anyhow::{ensure,Result};use psy_template_u124_markets::checkpoint_stream::*;
use std::{fs,time::Instant};
fn example(n:usize)->Manifest{let mut v=vec![0;FIELDS];v[..9].copy_from_slice(&[1,psy_config::PSY_NETWORK_MAGIC,1,1000,100,1,101,200,n as u64]);for i in[9,13,25,29,33,37]{v[i]=i as u64;}v[21..25].copy_from_slice(&[11,22,33,44]);Manifest{fields:v,members:(0..n).map(|i|Member{owner:200+i as u64,nonce:1,terms:[i as u64+1,2,3,4]}).collect()}}
#[test]fn manifests_exceed_four_without_splitting_or_reseeding_the_set()->Result<()>{for n in[1,2,4,5,8,9,17,65]{let(m,p)=prepare(example(n))?;ensure!(p.len()==(n+3)/4&&p.last().unwrap().after.cursor==n as u64,"complete continuous stream");let mut indices=p.iter().flat_map(|p|p.rows.iter().map(|r|r.index)).collect::<Vec<_>>();indices.sort();ensure!(indices==(0..n as u64).collect::<Vec<_>>(),"complete permutation");for w in p.windows(2){ensure!(w[0].after==w[1].before&&w[0].fields==w[1].fields,"cursor and original source retained");}ensure!(prepare(m).is_ok(),"exact prepared manifest reproducible");}Ok(())}
#[test]fn duplicate_missing_forged_and_replaced_manifests_reject()->Result<()>{let m=example(9);for idx in[0,1,4,8]{let mut bad=m.clone();if idx==0{bad.members.pop();}else if idx==1{bad.members[1].owner=bad.members[0].owner;}else if idx==4{bad.members[0].terms=[0;4];}else{bad.fields[17]=8;}ensure!(prepare(bad).is_err(),"invalid manifest accepted");}let(m,_)=prepare(m)?;let mut wrong=m;wrong.members[0].nonce+=1;ensure!(prepare(wrong).is_err(),"member replacement under frozen root");Ok(())}
#[test]fn an_untrusted_subset_is_not_a_block_coverage_certificate()->Result<()>{let(full,_)=prepare(example(9))?;let mut subset=example(9);subset.members.pop();subset.fields[8]=8;let(subset,_)=prepare(subset)?;ensure!(subset.fields[17..21]!=full.fields[17..21],"different scope must have a different root");Ok(())}
#[test]#[ignore="three bounded page proofs; fresh output; no financial execution"]
fn nine_orders_three_complete_pages_and_attacks()->Result<()>{let out=std::env::var("CHECKPOINT_STREAM_OUT")?;fs::create_dir(&out)?;let start=Instant::now();let c=PageCircuit::build();let build=start.elapsed().as_secs_f64();let(m,pages)=prepare(example(9))?;let mut proofs=vec![];let mut times=vec![];for(i,p)in pages.iter().enumerate(){let t=Instant::now();let proof=c.prove(p)?;c.verify(p,proof.clone())?;times.push(t.elapsed().as_secs_f64());fs::write(format!("{out}/page-{i}.bin"),bincode::serialize(&proof)?)?;proofs.push(proof);}
 let state=verify_chain(&c,&m,&pages,proofs.clone())?;ensure!(state.cursor==9,"all members processed");let mut rejected=vec![];
 for(label,index)in[("network",1),("market",3),("instance",9),("checkpoint",6),("root",17),("seed",21),("key",33)]{let mut wrong=pages[1].clone();wrong.fields[index]+=1;ensure!(c.verify(&wrong,proofs[1].clone()).is_err(),"scope substitution");rejected.push(label);}
 for(label,mutated,ps)in[("omitted-page",pages[1..].to_vec(),proofs[1..].to_vec()),("duplicate-page",vec![pages[0].clone(),pages[0].clone(),pages[2].clone()],proofs.clone()),("early-completion",pages[..2].to_vec(),proofs[..2].to_vec())]{ensure!(verify_chain(&c,&m,&mutated,ps).is_err(),"incomplete order accepted");rejected.push(label);}
 let mut wrong=pages[1].clone();wrong.rows[0].member.nonce+=1;let r=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||c.prove(&wrong)));ensure!(!matches!(r,Ok(Ok(_))),"forged membership witness");rejected.push("forged-membership-circuit");
 let mut wrong=pages[1].clone();wrong.rows.swap(0,1);let r=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||c.prove(&wrong)));ensure!(!matches!(r,Ok(Ok(_))),"wrong global order witness");rejected.push("reordered-circuit");
 for(name,value)in[("manifest.json",serde_json::to_value(&m)?),("pages.json",serde_json::to_value(&pages)?),("REPORT.json",serde_json::json!({"members":9,"pages":3,"pageCapacity":4,"buildSeconds":build,"proveAndVerifySeconds":times,"degreeBits":c.data.common.degree_bits(),"allConditionalPagesVerified":true,"rejected":rejected,"rawBlockCoverageAuthenticated":false,"marketOrSdKeyIntegrated":false,"fullUpsVerified":false,"networkAcceptance":false,"canBroadcast":false,"financialOperations":0,"scope":"complete finite-set order proof chain only; terms hashes, initial roots and producer seed synthetic"}))]{fs::write(format!("{out}/{name}"),serde_json::to_vec_pretty(&value)?)?;}Ok(())}
